import{_ as n,o as i,c as r,a2 as t}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"Ära der interdimensionalen Erkundung","description":"","frontmatter":{},"headers":[],"relativePath":"de/78-跨位面探索纪元.md","filePath":"de/78-跨位面探索纪元.md","lastUpdated":1789183869000}'),d={name:"de/78-跨位面探索纪元.md"};function s(u,e,a,o,l,g){return i(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="ara-der-interdimensionalen-erkundung" tabindex="-1">Ära der interdimensionalen Erkundung <a class="header-anchor" href="#ara-der-interdimensionalen-erkundung" aria-label="Permalink to &quot;Ära der interdimensionalen Erkundung&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Punkt</th><th>Inhalt</th></tr></thead><tbody><tr><td>Dokumentennummer</td><td>78</td></tr><tr><td>Modul</td><td>Historische Epochen und bedeutende Ereignisse</td></tr><tr><td>Kernschlüsselwörter</td><td>Interdimensionale Erkundung, große Entdeckungen der Ebenen, archäologisches Abkommen, zuerst beobachten dann eingreifen, interstellare Symbiose</td></tr></tbody></table><h2 id="_1-bedingungen-fur-die-eroffnung-der-ara-der-interdimensionalen-erkundung" tabindex="-1">1. Bedingungen für die Eröffnung der Ära der interdimensionalen Erkundung <a class="header-anchor" href="#_1-bedingungen-fur-die-eroffnung-der-ara-der-interdimensionalen-erkundung" aria-label="Permalink to &quot;1. Bedingungen für die Eröffnung der Ära der interdimensionalen Erkundung&quot;">​</a></h2><p>Die Ära der interdimensionalen Erkundung ist eine neue Ära, die nach der Gründung der Republik aller Rassen eröffnet wurde, und entspricht der Übergangsphase von der &quot;Bewusstseinsevolution&quot; zur &quot;interstellaren Symbiose&quot; im vierstufigen Aufstiegspfad. Die Eröffnung dieser Ära erfordert das gleichzeitige Reifen von drei Bedingungen:</p><ul><li><strong>Technische Bedingung</strong>: Die Raumgesetzestechnologie erreicht den Zustand des &quot;Quellraums&quot;, die stabile Öffnung von interdimensionalen Kanälen wird möglich; die Spiegelkopien- und Isolationsraumtechnologie reift und bietet technische Garantie für eine gering verschmutzende Erkundung</li><li><strong>Institutionelle Bedingung</strong>: Die Republik aller Rassen wird gegründet, die einheitliche Politik für die interdimensionale Erkundung und das archäologische Abkommen werden abgeschlossen</li><li><strong>Motivationsbedingung</strong>: Die Aufstiegsarbeit der bekannten Ebenen schreitet geordnet voran, die Zivilisation hat die Fähigkeit und den Willen, sich in unbekannte Ebenen auszudehnen</li></ul><p>Wenn diese drei Bedingungen gleichzeitig reifen, erklärt die Republik aller Rassen formell den Start des &quot;Großen Erkundungsplans&quot;, und die Ära der interdimensionalen Erkundung wird damit eröffnet.</p><h2 id="_2-grundprinzipien-der-interdimensionalen-erkundung" tabindex="-1">2. Grundprinzipien der interdimensionalen Erkundung <a class="header-anchor" href="#_2-grundprinzipien-der-interdimensionalen-erkundung" aria-label="Permalink to &quot;2. Grundprinzipien der interdimensionalen Erkundung&quot;">​</a></h2><p>Die interdimensionale Erkundung folgt streng den folgenden Grundprinzipien, die in das &quot;Grundgesetz der interdimensionalen Erkundung&quot; geschrieben wurden:</p><table tabindex="0"><thead><tr><th>Prinzip</th><th>Inhalt</th></tr></thead><tbody><tr><td>Zuerst beobachten, dann begrenzt eingreifen</td><td>Bei unbekannten Ebenen zunächst passive Beobachtung durchführen, erst nach ausreichendem Verständnis begrenzten Kontakt und Eingriff vornehmen</td></tr><tr><td>Gering verschmutzende Erkundung</td><td>Einsatz des archäologischen Plans mit Spiegelkopie + Isolationsraum, nur Wissen zurückübertragen, keine Materie und Leben hinein- oder hinausbringen</td></tr><tr><td>Schutz der einheimischen Zivilisation</td><td>Bei Ebenen mit einheimischer Zivilisation deren Recht auf autonome Entwicklung respektieren, das Symbiose-System nicht gewaltsam aufzwingen</td></tr><tr><td>Ressourcenteilen</td><td>Das in der Erkundung entdeckte Wissen und die Ressourcen gehören der gesamten Zivilisation, keine Organisation darf die Erkundungsergebnisse monopolisieren</td></tr><tr><td>Sicherheit zuerst</td><td>Die Sicherheit im Erkundungsprozess steht immer an erster Stelle, die Erkundung von risikoreichen Ebenen muss eine strenge Risikobewertung durchlaufen</td></tr></tbody></table><h2 id="_3-technische-mittel-der-erkundung" tabindex="-1">3. Technische Mittel der Erkundung <a class="header-anchor" href="#_3-technische-mittel-der-erkundung" aria-label="Permalink to &quot;3. Technische Mittel der Erkundung&quot;">​</a></h2><p>Die interdimensionale Erkundung nutzt integriert mehrere Kerntechnologien der symbiotischen Zivilisation:</p><ol><li><strong>Ebenen-Scanning-Technologie</strong>: Fernabtastung von Ebenen basierend auf dem Raumgesetz-Wahrnehmungsmodul, kann grundlegende Informationen (Raumstruktur, Energieniveau, Lebenszeichen usw.) erhalten, ohne die Zielebene zu berühren</li><li><strong>Archäologischer Plan mit Spiegelkopie</strong>: Hochpräzise Spiegelkopie der Zielebene durchführen, eingehende Forschung an der Spiegelkopie im Isolationsraum durchführen, nur Wissen zurückübertragen</li><li><strong>Interdimensionale Kommunikationssonde</strong>: Miniatur-Gesetzkommunikationsgerät, kann in die Zielebene zur Nahbeobachtung geschickt werden, Daten werden in Echtzeit über das interdimensionale Kommunikationsnetzwerk zurückübertragen</li><li><strong>Bewusstseinsdomänen-Wahrnehmung</strong>: Hochstufige Kultivierende nehmen die Zielebene über die Bewusstseinsdomäne fern wahr und erhalten Informationen auf Bewusstseinsebene, die die Scanning-Technologie nicht erfassen kann</li><li><strong>Fernbereitstellung von Ankern</strong>: Bei Ebenen mit hohem Sicherheitsniveau können temporäre Anker fernbereitgestellt werden, um stabile Verbindungskanäle aufzubauen</li></ol><h2 id="_4-organisation-und-durchfuhrung-der-erkundung" tabindex="-1">4. Organisation und Durchführung der Erkundung <a class="header-anchor" href="#_4-organisation-und-durchfuhrung-der-erkundung" aria-label="Permalink to &quot;4. Organisation und Durchführung der Erkundung&quot;">​</a></h2><p>Die interdimensionale Erkundung wird einheitlich von der &quot;Interdimensionalen Erkundungsbehörde&quot; der Republik aller Rassen organisiert und durchgeführt, und verfolgt das Modell der &quot;gestuften Erkundung&quot;:</p><table tabindex="0"><thead><tr><th>Erkundungsstufe</th><th>Zieltyp</th><th>Erkundungsmethode</th><th>Personalausstattung</th></tr></thead><tbody><tr><td>Erkundung der Stufe 1</td><td>Leblose öde Ebenen</td><td>Fernabtastung + Spiegelkopien-Forschung</td><td>Hauptsächlich technisches Team</td></tr><tr><td>Erkundung der Stufe 2</td><td>Ebenen mit niedrigem Leben</td><td>Spiegelkopien-Archäologie + begrenzte Felduntersuchung</td><td>Technisches Team + Biologen</td></tr><tr><td>Erkundung der Stufe 3</td><td>Ebenen mit einheimischer Zivilisation</td><td>Zuerst beobachten dann Kontakt, strenge Einhaltung des Kontaktprotokolls</td><td>Vollständiges Team + Diplomaten + ethische Beobachter</td></tr><tr><td>Erkundung der Stufe 4</td><td>Risikoreiche / unbekannte Ebenen</td><td>Nur Simulationsforschung im Isolationsraum, Feldkontakt verboten</td><td>Sicherheitsteam höchster Stufe</td></tr></tbody></table><p>Jedes Erkundungsprojekt muss den vollständigen Prozess &quot;Erkundungsantrag — Risikobewertung — ethische Prüfung — Genehmigung und Durchführung — Prozessüberwachung — Ergebnisteilen&quot; durchlaufen.</p><h2 id="_5-wichtige-entdeckungen-der-erkundungsara" tabindex="-1">5. Wichtige Entdeckungen der Erkundungsära <a class="header-anchor" href="#_5-wichtige-entdeckungen-der-erkundungsara" aria-label="Permalink to &quot;5. Wichtige Entdeckungen der Erkundungsära&quot;">​</a></h2><p>Nach der Eröffnung der Ära der interdimensionalen Erkundung machte die symbiotische Zivilisation eine Reihe wichtiger Entdeckungen:</p><ul><li><strong>Entdeckung neuer Rassen</strong>: In unbekannten Ebenen wurde eine große Anzahl zuvor unbekannter intelligenter Rassen entdeckt, die Abstammung aller Rassen wurde erheblich erweitert. Diese neuen Rassen schlossen sich nach freiwilliger Wahl schrittweise der Republik aller Rassen an</li><li><strong>Entdeckung neuer Gesetze</strong>: Es gibt Unterschiede in der Gesetzstruktur verschiedener Ebenen, bei der Erkundung wurden mehrere neue Gesetzvarianten entdeckt, die die theoretische Grundlage der dreihundert Kultivierungssysteme bereichert haben</li><li><strong>Ruinen alter Zivilisationen</strong>: Es wurden mehrere Ruinen ausgestorbener Zivilisationen aus der Vor-Anker-Ära entdeckt, durch Spiegelkopien-Archäologie wurde eine große Menge wertvolles historisches Wissen erlangt</li><li><strong>Symbiotische Zivilisationen anderer Ebenen</strong>: In einigen Ebenen wurden einheimische Zivilisationen entdeckt, die unabhängig das Konzept der Symbiose entwickelt haben, und bildeten eine raumübergreifende Gedankenresonanz mit der Anker-Symbiose-Zivilisation</li><li><strong>Erkundung der Universumsgrenzen</strong>: Die Erkundung berührt schrittweise die bekannten Grenzen von Hengyuanzhou, das Verständnis der Gesamtstruktur des Universums vertieft sich ständig</li></ul><h2 id="_6-herausforderungen-und-reflexionen-in-der-erkundung" tabindex="-1">6. Herausforderungen und Reflexionen in der Erkundung <a class="header-anchor" href="#_6-herausforderungen-und-reflexionen-in-der-erkundung" aria-label="Permalink to &quot;6. Herausforderungen und Reflexionen in der Erkundung&quot;">​</a></h2><p>Die interdimensionale Erkundung verlief nicht immer reibungslos, im Prozess stieß sie auch auf Herausforderungen:</p><ul><li><strong>Kulturkonflikt</strong>: Beim Kontakt mit einheimischen Zivilisationen traten kulturelle Missverständnisse und Konflikte auf, was die kontinuierliche Verbesserung des Kontaktprotokolls vorantrieb</li><li><strong>Ethische Kontroverse der Erkundung</strong>: Es gab eine anhaltende ethische Debatte darüber, &quot;ob man einheimische Zivilisationen aktiv kontaktieren sollte&quot;, schließlich bildete sich der Konsens &quot;nicht aktiv, nicht ausweichen, Wahl respektieren&quot;</li><li><strong>Sicherheitsunfall</strong>: Bei der Erkundung risikoreicher Ebenen ereignete sich ein Unfall mit beschädigter Isolationsraum-Barriere; obwohl keine schwerwiegenden Folgen eintraten, trieb dies die weitere Verbesserung der Sicherheitsstandards voran</li><li><strong>Ressourcenallokation</strong>: Die großflächige Erkundung erfordert den Verbrauch großer Ressourcenmengen, das Gleichgewicht zwischen Erkundungsinvestitionen und Investitionen in das lokale Wohlergehen wurde zum Mittelpunkt der politischen Debatte</li></ul><h2 id="schlussfolgerung" tabindex="-1">Schlussfolgerung <a class="header-anchor" href="#schlussfolgerung" aria-label="Permalink to &quot;Schlussfolgerung&quot;">​</a></h2><p>Die Ära der interdimensionalen Erkundung ist das &quot;Große Zeitalter der Entdeckungen&quot; der Anker-Symbiose-Zivilisation. Sie erweiterte den Horizont der Zivilisation von den bekannten Ebenen auf das gesamte Universum und vertiefte gleichzeitig mit der Entdeckung neuer Welten auch das Verständnis für sich selbst. Der gering verschmutzende Erkundungsplan mit Spiegelkopie + Isolationsraum unterscheidet die Erkundung der symbiotischen Zivilisation von jeder räuberischen kolonialen Expansion in der Geschichte — was wir mitbringen, ist nicht Eroberung und Plünderung, sondern Respekt und Wissen; was wir zurückbringen, ist nicht Ressourcen und Sklaven, sondern Verständnis und Weisheit. Wenn die erkundeten Ebenen ausreichend zahlreich und das Anker-Netzwerk ausreichend dicht ist, wird sich die Tür zur Ära der interstellaren Symbiose langsam öffnen.</p><h2 id="verwandte-dokumente" tabindex="-1">Verwandte Dokumente <a class="header-anchor" href="#verwandte-dokumente" aria-label="Permalink to &quot;Verwandte Dokumente&quot;">​</a></h2><ul><li>77-Gründung der Republik aller Rassen</li><li>79-Ausblick auf die Ära der interstellaren Symbiose</li><li>84-Grundprogramm des archäologischen Abkommens</li></ul>',26)])])}const k=n(d,[["render",s]]);export{c as __pageData,k as default};
